import {Matrix4,Vector3} from 'three';
import {clothPins,ropeShape} from './cloth-config.js';
import {deformableParticleCount} from './deformable-distribution.js';
import {validDeformableDistanceLimits} from './deformable-distance-limits.js';
import {componentDefaultValues,editComponentProperty,validComponentProperties} from './scene-components.js';
import {sceneWorldMatrix} from './scene-runtime.js';
class Queue{
 constructor(){this.rows=[];}
 before(a,b){return a.distance<b.distance||a.distance===b.distance&&(a.anchor<b.anchor||a.anchor===b.anchor&&a.index<b.index);}
 push(row){const a=this.rows;let i=a.length;a.push(row);while(i){const p=(i-1)>>1;if(!this.before(row,a[p]))break;a[i]=a[p];i=p;}a[i]=row;}
 pop(){const a=this.rows,first=a[0],last=a.pop();if(a.length){let i=0;while(i*2+1<a.length){let child=i*2+1;if(child+1<a.length&&this.before(a[child+1],a[child]))child++;if(!this.before(a[child],last))break;a[i]=a[child];i=child;}a[i]=last;}return first;}
}
export function generateClothTethers(p,{matrix,stretch=1.1,dimension=3}={}){
 const rope=ropeShape(p),count=deformableParticleCount(p),columns=rope?p.particles:p.columns,rows=rope?1:p.rows;if(!Number.isSafeInteger(count)||count<2||count>65536||!Number.isSafeInteger(columns)||columns<2||!Number.isSafeInteger(rows)||rows<1||!Number.isFinite(stretch)||stretch<1||stretch>10||![2,3].includes(dimension))throw Error('연결을 생성할 입자 형상·여유 배율을 확인하세요.');
 const transform=new Matrix4();if(matrix){const value=matrix.isMatrix4?matrix.elements:matrix;if(!Array.isArray(value)||value.length!==16||!value.every(Number.isFinite)||value[3]!==0||value[7]!==0||value[11]!==0||value[15]!==1)throw Error('연결 생성의 월드 변환을 확인하세요.');transform.fromArray(value);}
 const origin=new Vector3().applyMatrix4(transform),a=new Vector3(),b=new Vector3();let horizontal,vertical=0;if(rope){if(!Array.isArray(p.start)||!Array.isArray(p.end)||p.start.length!==3||p.end.length!==3||![...p.start,...p.end].every(Number.isFinite))throw Error('로프 시작과 끝을 확인하세요.');a.fromArray(p.start).applyMatrix4(transform);b.fromArray(p.end).applyMatrix4(transform);if(dimension===2){a.z=0;b.z=0;}horizontal=a.distanceTo(b)/(count-1);}else{if(rows<2||!Number.isFinite(p.width)||p.width<=0||!Number.isFinite(p.height)||p.height<=0)throw Error('천 격자 크기를 확인하세요.');a.set(p.width/(columns-1),0,0).applyMatrix4(transform);horizontal=Math.hypot(a.x-origin.x,a.y-origin.y,dimension===2?0:a.z-origin.z);a.set(0,p.height/(rows-1),0).applyMatrix4(transform);vertical=Math.hypot(a.x-origin.x,a.y-origin.y,dimension===2?0:a.z-origin.z);}if(!Number.isFinite(horizontal)||!Number.isFinite(vertical)||!(horizontal>1e-10)||!rope&&!(vertical>1e-10))throw Error('길이가 없는 입자 축은 연결을 생성할 수 없어요.');
 const pins=clothPins(rope?{...p,columns,rows:1}:p);if(!pins.size)throw Error('먼저 고정 입자를 지정하세요.');if(pins.size===count){if(!validDeformableDistanceLimits({...p,distanceTethers:[]}))throw Error('입자 제약 속성을 확인하세요.');return{tethers:[],particles:count,anchors:count,metric:rope?'rope-chain':'grid4-geodesic',stretch};}const distances=new Float64Array(count).fill(Infinity),anchors=new Int32Array(count).fill(-1),queue=new Queue();for(const index of [...pins].sort((a,b)=>a-b)){distances[index]=0;anchors[index]=index;queue.push({index,distance:0,anchor:index});}
 const relax=(index,distance,anchor)=>{if(!Number.isFinite(distance))return;const old=distances[index],tolerance=1e-10*Math.max(1,distance,Number.isFinite(old)?old:0);if(!Number.isFinite(old)||distance<old-tolerance||Math.abs(distance-old)<=tolerance&&anchor<anchors[index]){distances[index]=distance;anchors[index]=anchor;queue.push({index,distance,anchor});}};
 while(queue.rows.length){const current=queue.pop(),i=current.index;if(current.distance!==distances[i]||current.anchor!==anchors[i])continue;const u=Math.floor(i/rows),v=i%rows;if(u)relax(i-rows,current.distance+horizontal,current.anchor);if(u+1<columns)relax(i+rows,current.distance+horizontal,current.anchor);if(!rope&&v)relax(i-1,current.distance+vertical,current.anchor);if(!rope&&v+1<rows)relax(i+1,current.distance+vertical,current.anchor);}
 const tethers=[];for(let index=0;index<count;index++)if(!pins.has(index))tethers.push({index,anchor:anchors[index],distance:distances[index]*stretch});if(!validDeformableDistanceLimits({...p,distanceTethers:tethers}))throw Error('생성된 최대 거리가 입자 제약 범위를 벗어났어요.');return{tethers,particles:count,anchors:pins.size,metric:rope?'rope-chain':'grid4-geodesic',stretch};
}
export function editClothTethers(data,{kind='scene',target,component,stretch=1.1}={}){if(!['scene','blueprint'].includes(kind))throw Error('천 연결 문서 종류를 확인하세요.');const object=kind==='scene'?data.objects?.find(o=>o.id===target):data;if(!object)throw Error('연결을 생성할 오브젝트가 없어요.');const matches=(object.components||[]).filter(c=>['Cloth','Rope2D'].includes(c.type)&&(!component||[c.id,c.name,c.type].includes(component)));if(matches.length!==1)throw Error('생성할 천·로프 컴포넌트를 고유하게 지정하세요.');const c=matches[0],p={...componentDefaultValues(c.type),...c.properties};if(!validComponentProperties(c.type,p))throw Error('천·로프 속성을 확인하세요.');const generated=generateClothTethers(p,{stretch,dimension:c.type==='Rope2D'?2:3,matrix:kind==='scene'?sceneWorldMatrix(object,data.objects):undefined}),next=editComponentProperty(c.type,p,'distanceTethers',generated.tethers);if(!validComponentProperties(c.type,next))throw Error('생성된 연결 속성을 확인하세요.');c.properties=next;return{target:kind==='scene'?object.id:null,component:c.id,particles:generated.particles,anchors:generated.anchors,tethers:generated.tethers.length,metric:generated.metric,stretch};}
export const clothTetherGenerationContract=Object.freeze({function:'generateClothTethers(properties,{matrix?,stretch=1.1,dimension=3}); editClothTethers(document,{kind,target?,component?,stretch?})',source:'Existing authored hard pins including pinOverrides; no pins rejects, pinned particles receive no tether. Optional full affine matrix; Rope2D uses projected XY length, blueprint definition uses unit actor frame.',metric:'Multi-source shortest paths on authored regular grid4 or linear rope adjacency. World lengths per grid axis/rope segment, stable lowest pin index on equal distances. Not straight-line nearest-pin nor arbitrary mesh geodesics.',result:'One maximum-distance row per free particle: {index,anchor,distance=geodesic*stretch}; validates existing limits before any edit, actor/physics data remain unchanged by the generator.',authoring:'Existing scene/BP distance controls, generate as one ordinary validated field change/Undo. scene.cloth.tethers / blueprint.cloth.tethers use expectedRevision/dryRun/includeData(defaultfalse) in the existing document path. No runtime graph search or persistent worker/cache.',limits:'Authored regular topology only; no holes/tearing/skinned arbitrary mesh/automatic runtime pin changes or coupled contact reaction. Generation does not raise physical capacities or distance units.'});
